AND c.is_delete = 0 AND c.status = 'published'
AND (c.visibility = 'public' OR c.author_id = #{userId})
AND c.type = #{type}

mapper.select:
SELECT h.content_id
FROM user_view_history h
         INNER JOIN content c ON h.content_id = c.id
WHERE h.user_id = #{userId}

ORDER BY h.view_time DESC, h.content_id DESC
    LIMIT #{offset}, #{size}
